/**
 * Instrument Style 2D Java Implementation.
 * 
 * Generated by AMF for model: Markets.metaabm in project: org.eclipse.amp.amf.examples.escape 
 */
public class InstrumentStyle2DFigureProvider extends DefaultFigureProvider {

	private static IFigureProvider singleton;

	public IFigure getFigure(Object object) {
		IFigure figure = null;
		Color color = null;
		Instrument actions = (Instrument) object;
		Instrument instrumentRule = actions;
		if (instrumentRule.getStatus() == StatusEnum.held) {
			if (figure == null) {
				figure = Shapes.createOval();
			}
			color = ColorConstants.gray;

			figure.setBackgroundColor(color);
			((Shape) figure).setFill(true);
		}
		if (instrumentRule.getStatus() == StatusEnum.offerred) {
			if (figure == null) {
				figure = Shapes.createOval();
			}
			color = ColorConstants.black;

			figure.setBackgroundColor(color);
			((Shape) figure).setFill(true);
		}
		return figure;
	}

	public static IFigureProvider getDefault() {
		if (singleton == null) {
			singleton = new InstrumentStyle2DFigureProvider();
		}
		return singleton;
	}
}
